<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; use Illuminate\Database\Eloquent\Relations\HasMany;
class GoodsReceipt extends Model { protected $fillable=['grn_number','purchase_order_id','warehouse_id','received_date','supplier_invoice_number','supplier_invoice_date','due_date','status','note','received_by']; protected $casts=['received_date'=>'date','supplier_invoice_date'=>'date','due_date'=>'date']; public function purchaseOrder():BelongsTo{return $this->belongsTo(PurchaseOrder::class);} public function warehouse():BelongsTo{return $this->belongsTo(Warehouse::class);} public function receiver():BelongsTo{return $this->belongsTo(User::class,'received_by');} public function items():HasMany{return $this->hasMany(GoodsReceiptItem::class);} }
